with feeders as (
    select
        md5(upper('HUB_PARTY|' || (HUB_PARTY_BK__HOSID))) as HUB_PARTY_HK
        , cast(null as varchar) as CONTACT_POINT_TYPE
        , cast(null as varchar) as CONTACT_PRIORITY_ORDER
        , CONTACT_PERSON as CONTACT_PERSON_NAME
        , DESIGNATION as CONTACT_PERSON_DESIGNATION
        , cast(null as varchar) as CONTACT_POINT
        , 'BJAZ_HM_HOSPITAL_MASTER' as RECORD_SOURCE
        , 'opus_health_legacy_v4' as SOURCE_RUN
        , current_timestamp() as LOAD_DATETIME
    from {{ ref('stage_hm_hospital_master') }}
    where (nullif(trim(HOSID),'')) is not null
    union all
    select
        md5(upper('HUB_PARTY|' || (HUB_PARTY_BK__HOSID))) as HUB_PARTY_HK
        , cast(null as varchar) as CONTACT_POINT_TYPE
        , cast(null as varchar) as CONTACT_PRIORITY_ORDER
        , cast(null as varchar) as CONTACT_PERSON_NAME
        , cast(null as varchar) as CONTACT_PERSON_DESIGNATION
        , INS_DEPT_CONTACT2 as CONTACT_POINT
        , 'BJAZ_HM_HOSPITAL_MASTER_EXTN' as RECORD_SOURCE
        , 'opus_health_legacy_v4' as SOURCE_RUN
        , current_timestamp() as LOAD_DATETIME
    from {{ ref('stage_hm_hospital_master_extn') }}
    where (nullif(trim(HOSID),'')) is not null
    union all
    select
        md5(upper('HUB_PARTY|' || (HUB_PARTY_BK__IMD_CODE))) as HUB_PARTY_HK
        , cast(null as varchar) as CONTACT_POINT_TYPE
        , cast(null as varchar) as CONTACT_PRIORITY_ORDER
        , CONTACT_PERSON as CONTACT_PERSON_NAME
        , cast(null as varchar) as CONTACT_PERSON_DESIGNATION
        , cast(null as varchar) as CONTACT_POINT
        , 'BJAZ_ENROLL_POL_DTLS' as RECORD_SOURCE
        , 'opus_health_v2' as SOURCE_RUN
        , current_timestamp() as LOAD_DATETIME
    from {{ ref('stage_enroll_pol_dtls') }}
    where (nullif(trim(IMD_CODE),'')) is not null
    union all
    select
        md5(upper('HUB_PARTY|' || (HUB_PARTY_BK__CONTRACT_ID_INSURED_NAME))) as HUB_PARTY_HK
        , 'CONTACT_PERSON' as CONTACT_POINT_TYPE
        , '1' as CONTACT_PRIORITY_ORDER
        , CONTACT_PERSON as CONTACT_PERSON_NAME
        , cast(null as varchar) as CONTACT_PERSON_DESIGNATION
        , cast(null as varchar) as CONTACT_POINT
        , 'BJAZ_POLICY_SUMMARY' as RECORD_SOURCE
        , 'opus_health_delta3' as SOURCE_RUN
        , current_timestamp() as LOAD_DATETIME
    from {{ ref('stage_policy_summary') }}
    where (md5(normalise(upper(nullif(coalesce(nullif(trim(CONTRACT_ID),''),'') || '|INSURED|' || coalesce(nullif(trim(INSURED_NAME),''),''), '|INSURED|'))))) is not null
),

resolved as (
    select
        HUB_PARTY_HK,
        CONTACT_POINT_TYPE,
        CONTACT_PRIORITY_ORDER,
        coalesce(max(case when SOURCE_RUN = 'opus_health_v2' then CONTACT_PERSON_NAME end),
                 max(case when SOURCE_RUN = 'opus_health_legacy_v4' then CONTACT_PERSON_NAME end),
                 max(case when SOURCE_RUN = 'opus_health_delta3' then CONTACT_PERSON_NAME end)) as CONTACT_PERSON_NAME,
        max(case when SOURCE_RUN = 'opus_health_legacy_v4' then CONTACT_PERSON_DESIGNATION end) as CONTACT_PERSON_DESIGNATION,
        max(case when SOURCE_RUN = 'opus_health_legacy_v4' then CONTACT_POINT end) as CONTACT_POINT,
        min(RECORD_SOURCE) as RECORD_SOURCE,
        min(SOURCE_RUN) as SOURCE_RUN,
        min(LOAD_DATETIME) as LOAD_DATETIME
    from feeders
    group by HUB_PARTY_HK, CONTACT_POINT_TYPE, CONTACT_PRIORITY_ORDER
),

hashed as (
    select
        *,
        case when CONTACT_POINT_TYPE is not null or CONTACT_PRIORITY_ORDER is not null or CONTACT_PERSON_NAME is not null or CONTACT_PERSON_DESIGNATION is not null or CONTACT_POINT is not null
                     then md5(upper(coalesce(cast(CONTACT_POINT_TYPE as varchar), '') || '|' || coalesce(cast(CONTACT_PRIORITY_ORDER as varchar), '') || '|' || coalesce(cast(CONTACT_PERSON_NAME as varchar), '') || '|' || coalesce(cast(CONTACT_PERSON_DESIGNATION as varchar), '') || '|' || coalesce(cast(CONTACT_POINT as varchar), '')))
                end as SAT_COMMON_CONTACT_HASHDIFF
    from resolved
)

select * from hashed
where HUB_PARTY_HK is not null
  and SAT_COMMON_CONTACT_HASHDIFF is not null
